/// <summary>
/// The service class for Planner code clean up batch job.
/// </summary>
class METPlannerCodeCleanupService extends SysOperationServiceBase
{
}

Method.Source:
    /// <summary>
    /// The processing method for Planner code clean up batch job.
    /// </summary>
    public void processOperation()
    {
        METVendParameters metVendParameters = METVendParameters::find();
        METPlannerCodeAssignmentRules metPlannerCodeAssignmentRules;
        utcdatetime dateTimeToStart;

        if (metVendParameters.PlannerCodeCleanupDays)
        {            
            dateTimeToStart = DateTimeUtil::date(DateTimeUtil::getSystemDateTime()) - metVendParameters.PlannerCodeCleanupDays;

            ttsbegin;

            delete_from metPlannerCodeAssignmentRules
                    where metPlannerCodeAssignmentRules.RuleEnabledStatusLastModified <= dateTimeToStart;

            ttscommit;
        }
    }
